// These modules are copied or generated by scripts/build-profile-share.cjs.
// eslint-disable-next-line import/no-unresolved
import cloudbase from './cloudbase.js';
// eslint-disable-next-line import/no-unresolved
import config from './config.js';

const ownerId = new URLSearchParams(location.search).get('profile') ?? '';
const element = id => document.getElementById(id);
const name = element('name');
const status = element('status');
const bio = element('bio');
const avatar = element('avatar');
const open = element('open');
const retry = element('retry');

function avatarUrl(app, path) {
  const preset = /^xingji-preset:(photo-[a-z-]+)$/.exec(path ?? '');
  if (preset) return `./avatars/${preset[1]}.jpg`;

  const directory = `xingji-public:${ownerId}/avatars/`;
  if (!path?.startsWith(directory) || !/^[a-f0-9]{64}$/i.test(path.slice(directory.length))) return null;
  return app.storage.from('xingji-public').getPublicUrl(path.slice('xingji-public:'.length)).data.publicUrl;
}

async function loadProfile() {
  name.textContent = '正在打开个人主页';
  status.textContent = '';
  retry.hidden = true;
  try {
    const app = cloudbase.init({ env: config.env, region: config.region, accessKey: config.accessKey });
    const { data, error } = await app.rdb().from('xingji_public_profiles')
      .select('display_name,bio,avatar_path').eq('owner_id', ownerId).eq('is_public', true).limit(1);
    if (error) throw error;
    const profile = data?.[0];
    if (!profile) {
      name.textContent = '主页暂不可用';
      status.textContent = '此主页未公开或已不存在。';
      return;
    }

    const displayName = profile.display_name?.trim() || '行路的人';
    const imageUrl = avatarUrl(app, profile.avatar_path);
    name.textContent = displayName;
    bio.textContent = profile.bio?.trim() || '';
    bio.hidden = !bio.textContent;
    element('initial').textContent = Array.from(displayName)[0];
    avatar.hidden = false;
    if (imageUrl) {
      const image = document.createElement('img');
      image.alt = '';
      image.addEventListener('error', () => image.remove(), { once: true });
      image.src = imageUrl;
      avatar.append(image);
    }
    open.href = `xingji://shared-profile/${ownerId}`;
    open.hidden = false;
  } catch {
    name.textContent = '暂时无法加载主页';
    status.textContent = '请检查网络连接后重试。';
    retry.hidden = false;
  }
}

if (/^[A-Za-z0-9_-]{6,128}$/.test(ownerId)) {
  retry.addEventListener('click', loadProfile);
  void loadProfile();
} else {
  name.textContent = '分享链接无效';
  status.textContent = '请检查链接，或向分享者索取新链接。';
}
